INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RamboRogers/cyber-inference/run-thor', 'community', 'RamboRogers', 'cyber-inference', 'RamboRogers/cyber-inference', 'run-thor', 0, 0, 50, '2026-02-18T01:08:43.539Z', '2026-02-19T00:56:47.978Z', NULL, '{"id":"RamboRogers/cyber-inference/run-thor","name":"run-thor","description":{"zh":"Cyber-Inference是基于llama.cpp的Web GUI管理工具，用于运行OpenAI兼容的推理服务器。Thor是GPU实验室服务器，用于集成测试","ja":"Cyber-Inferenceはllama.cppベースのWeb GUI管理ツールであり、OpenAI互換の推論サーバーを実行するために使用されます。ThorはGPUラボサーバーであり、統合テストに使用されます","ko":"Cyber-Inference는 llama.cpp 기반의 Web GUI 관리 도구로 OpenAI 호환 인퍼런스 서버를 실행하는 데 사용됩니다. Thor는 GPU 실험실 서버로 통합 테스트에 사용됩니다","es":"Run-Thor es una herramienta de gestión web para servidores de inferencia compatibles con OpenAI, con gestión de modelos automática y asignación de recursos dinámica","fr":"Run-Thor est un outil de gestion web pour les serveurs d''inférence compatibles OpenAI, avec gestion de modèles automatique et allocation de ressources dynamique","de":"Run-Thor ist ein Web-GUI-Management-Tool für OpenAI-kompatible Inferenz-Server mit automatischer Modellverwaltung und dynamischer Ressourcenzuweisung","pt":"O Run-Thor é uma ferramenta de gerenciamento de inferência para servidores de inferência compatíveis com OpenAI, com recursos de gerenciamento de modelo e alocação de recursos dinâmica","ru":"Run-Thor - это инструмент управления выводом для серверов вывода, совместимых с OpenAI, с функциями управления моделью и динамическим распределением ресурсов","ar":"Run-Thor هي أداة إدارة الاستدلال للخادمات المتوافقة مع OpenAI، مع ميزات إدارة النماذج وتخصيص الموارد الديناميكي","en":"Cyber-Inference is a web GUI management tool for running OpenAI-compatible inference servers. Built on llama.cpp, it provides automatic model management, dynamic resource allocation, and a beautiful cyberpunk-themed interface designed for edge deployment."},"seo":{"title":{"zh":"运行Thor：Cyber-Inference部署测试","ja":"Thorを実行する：Cyber-Inferenceのデプロイとテスト","ko":"Thor 실행: Cyber-Inference 배포 및 테스트","es":"Run-Thor: Entorno de prueba de inferencia de IA","fr":"Run-Thor : Environnement de test d''inférence IA","de":"Run-Thor: Umgebung für IA-Inferenz-Tests","pt":"Run-Thor: Ferramenta de Gerenciamento de Inferência","ru":"Run-Thor: Инструмент управления выводом","ar":"Run-Thor: أداة إدارة الاستدلال","en":"run-thor"},"description":{"zh":"Cyber-Inference是基于llama.cpp的Web GUI管理工具，用于运行OpenAI兼容的推理服务器。Thor是GPU实验室服务器，用于集成测试","ja":"Cyber-Inferenceはllama.cppベースのWeb GUI管理ツールであり、OpenAI互換の推論サーバーを実行するために使用されます。ThorはGPUラボサーバーであり、統合テストに使用されます","ko":"Cyber-Inference는 llama.cpp 기반의 Web GUI 관리 도구로 OpenAI 호환 인퍼런스 서버를 실행하는 데 사용됩니다. Thor는 GPU 실험실 서버로 통합 테스트에 사용됩니다","es":"Run-Thor es una herramienta de gestión web para servidores de inferencia compatibles con OpenAI, con gestión de modelos automática y asignación de recursos d...","fr":"Run-Thor est un outil de gestion web pour les serveurs d''inférence compatibles OpenAI, avec gestion de modèles automatique et allocation de ressources dynamique","de":"Run-Thor ist ein Web-GUI-Management-Tool für OpenAI-kompatible Inferenz-Server mit automatischer Modellverwaltung und dynamischer Ressourcenzuweisung","pt":"O Run-Thor é uma ferramenta de gerenciamento de inferência para servidores de inferência compatíveis com OpenAI, com recursos de gerenciamento de modelo e al...","ru":"Run-Thor - это инструмент управления выводом для серверов вывода, совместимых с OpenAI, с функциями управления моделью и динамическим распределением ресурсов","ar":"Run-Thor هي أداة إدارة الاستدلال للخادمات المتوافقة مع OpenAI، مع ميزات إدارة النماذج وتخصيص الموارد الديناميكي","en":"Cyber-Inference is a web GUI management tool for running OpenAI-compatible inference servers. Built on llama.cpp, it provides automatic model management, dyn..."},"definition":{"en":"Cyber-Inference is a web GUI management tool for running OpenAI-compatible inference servers. Built on llama.cpp, it provides automatic model management, dynamic resource allocation, and a beautiful cyberpunk-themed interface designed for edge deployment."},"features":{"zh":["自动模型管理","动态资源分配","美丽的赛博朋克主题界面","边缘部署支持","SSH访问","生产环境测试"],"ja":["自動モデルの管理","動的リソース割り当て","美しいサイバーパンクテーマのインターフェイス","エッジデプロイのサポート","SSHアクセス","生产環境のテスト"],"ko":["자동 모델 관리","동적 리소스 할당","아름다운 사이버펑크 테마 인터페이스","엣지 배포 지원","SSH 접근","생산 환경 테스트"],"es":["Gestión de modelos automática","Asignación de recursos dinámica","Interfaz de usuario con tema ciberpunk","Despliegue en el servidor de laboratorio de GPU","Acceso vía SSH","Entorno de prueba de producción"],"fr":["Gestion de modèles automatique","Allocation de ressources dynamique","Interface utilisateur avec thème cyberpunk","Déploiement sur le serveur de laboratoire GPU","Accès via SSH","Environnement de test de production"],"de":["Automatische Modellverwaltung","Dynamische Ressourcenzuweisung","Benutzeroberfläche mit Cyberpunk-Design","Bereitstellung auf dem GPU-Lab-Server","Zugriff über SSH","Produktionsähnliches Testumfeld"],"pt":["Gerenciamento de modelo automático","Alocação de recursos dinâmica","Interface temática cyberpunk","Implantação em borda","Acesso via SSH","Ambiente de teste de produção"],"ru":["Автоматическое управление моделью","Динамическое распределение ресурсов","Интерфейс в стиле киберпанк","Развертывание на краю","Доступ по SSH","Тестовая среда производства"],"ar":["إدارة النموذج الآلي","تخصيص الموارد الديناميكي","واجهة المستخدم في نمط سايبربانك","التثبيت على الحافة","الوصول عبر SSH","بيئة اختبار الإنتاج"]},"keywords":{"zh":["Cyber-Inference","Thor","GPU实验室服务器","自动模型管理","动态资源分配","边缘部署","SSH访问","生产环境测试"],"ja":["Cyber-Inference","Thor","GPUラボサーバー","自動モデルの管理","動的リソース割り当て","エッジデプロイ","SSHアクセス","生产環境のテスト"],"ko":["Cyber-Inference","Thor","GPU 실험실 서버","자동 모델 관리","동적 리소스 할당","엣지 배포","SSH 접근","생산 환경 테스트"],"es":["inferencia de IA","servidores de inferencia","OpenAI","gestión de modelos","asignación de recursos","despliegue en la nube","pruebas de integración","entorno de prueba"],"fr":["inférence IA","serveurs d''inférence","OpenAI","gestion de modèles","allocation de ressources","déploiement dans le cloud","tests d''intégration","environnement de test"],"de":["IA-Inferenz","Inferenz-Server","OpenAI","Modellverwaltung","Ressourcenzuweisung","Bereitstellung in der Cloud","Integrationstests","Testumfeld"],"pt":["Run-Thor","ferramenta de gerenciamento de inferência","servidores de inferência","OpenAI","gerenciamento de modelo","alocação de recursos","implantação em borda"],"ru":["Run-Thor","инструмент управления выводом","серверы вывода","OpenAI","управление моделью","распределение ресурсов","развертывание на краю"],"ar":["Run-Thor","أداة إدارة الاستدلال","خادمات الاستدلال","OpenAI","إدارة النموذج","تخصيص الموارد","التثبيت على الحافة"]}},"owner":"RamboRogers","repo":"cyber-inference","repoPath":"RamboRogers/cyber-inference","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.539Z","topics":[],"category":"community","skillMd":{"name":"run-thor","description":"Deploy and test cyber-inference on the Thor lab server. Use when the user wants to test on Thor, deploy to Thor, run on Thor, verify the server, or mentions thor.lab.","bodyPreview":"# Deploy & Test on Thor\n\nThor is the GPU lab server used for integration testing of cyber-inference. It is accessible via SSH and hosts the production-like test environment.\n\n## Connection Details\n\n| Field | Value |\n|-------|-------|\n| Host | `thor.lab` |\n| User | `matt` |\n| SSH | `ssh matt@thor.lab` |\n| Project path | `/home/matt/Local/cyber-inference` |\n| Server URL | `http://thor.lab:8337` |\n\n## Deploy Workflow\n\nFollow these steps in order. Each depends on the previous.\n\n### 1. Commit & Push","body":"# Deploy & Test on Thor\n\nThor is the GPU lab server used for integration testing of cyber-inference. It is accessible via SSH and hosts the production-like test environment.\n\n## Connection Details\n\n| Field | Value |\n|-------|-------|\n| Host | `thor.lab` |\n| User | `matt` |\n| SSH | `ssh matt@thor.lab` |\n| Project path | `/home/matt/Local/cyber-inference` |\n| Server URL | `http://thor.lab:8337` |\n\n## Deploy Workflow\n\nFollow these steps in order. Each depends on the previous.\n\n### 1. Commit & Push (local machine)\n\n```bash\ngit add -A && git commit -m \"<message>\" && git push\n```\n\n### 2. Pull on Thor (remote)\n\n```bash\nssh matt@thor.lab \"cd /home/matt/Local/cyber-inference && git pull\"\n```\n\n### 3. Start the Server (remote)\n\nThe server runs via `start.sh` which handles `uv sync` and auto-restart.\n\n```bash\n# Interactive (see logs live) - use for debugging\nssh -t matt@thor.lab \"cd /home/matt/Local/cyber-inference && ./start.sh\"\n\n# Background (detached) - use for long-running tests\nssh matt@thor.lab \"cd /home/matt/Local/cyber-inference && nohup ./start.sh > /tmp/cyber-inference.log 2>&1 &\"\n```\n\nCUDA PyTorch wheels are verified automatically when NVIDIA hardware is detected.\n\n### 4. Verify the Server\n\n```bash\n# Health check\ncurl -s http://thor.lab:8337/health\n\n# List models\ncurl -s http://thor.lab:8337/v1/models | python3 -m json.tool\n\n# System status\ncurl -s http://thor.lab:8337/admin/status | python3 -m json.tool\n\n```\n\nThe web GUI is available at: `http://thor.lab:8337`\n\n### 5. Test Inference\n\n```bash\n# Chat completion\ncurl -s http://thor.lab:8337/v1/chat/completions \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\"model\": \"<model_name>\", \"messages\": [{\"role\": \"user\", \"content\": \"Hello\"}]}'' \\\n  | python3 -m json.tool\n\n# Embeddings\ncurl -s http://thor.lab:8337/v1/embeddings \\\n  -H \"Content-Type: application/json\" \\\n  -d ''{\"model\": \"<model_name>\", \"input\": \"test text\"}'' \\\n  | python3 -m json.tool\n```\n\n## Quick One-Liner Deploy\n\nPull latest and restart in one command:\n\n```bash\nssh -t matt@thor.lab \"cd /home/matt/Local/cyber-inference && git pull && ./start.sh\"\n```\n\n## Troubleshooting\n\n- **Server won''t start**: Check logs with `ssh matt@thor.lab \"tail -50 /tmp/cyber-inference.log\"`\n- **Port in use**: Kill existing process with `ssh matt@thor.lab \"pkill -f ''cyber-inference serve''\"`\n- **Check running processes**: `ssh matt@thor.lab \"ps aux | grep cyber-inference\"`\n- **GPU/CUDA issues**: `ssh matt@thor.lab \"nvidia-smi\"`\n"},"lastSynced":"2026-02-19T00:56:47.978Z","qualityScore":50}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('vendelieu/telegram-bot/setup-bot-handlers', 'community', 'vendelieu', 'telegram-bot', 'vendelieu/telegram-bot', 'setup-bot-handlers', 0, 0, 55, '2026-02-18T01:08:43.539Z', '2026-02-19T01:13:06.130Z', NULL, '{"id":"vendelieu/telegram-bot/setup-bot-handlers","name":"setup-bot-handlers","description":{"zh":"Kotlin DSL Telegram Bot API, DSL","ja":"Kotlin DSL Telegram Bot API, DSL","ko":"Kotlin DSL Telegram Bot API, DSL","es":"La API de Telegram Bot con Kotlin DSL permite definir funcionalidades de bot de manera sencilla. Conoce las dos formas de configurar manejadores de bot","fr":"L''API de bot Telegram avec Kotlin DSL permet de définir les fonctionnalités de bot de manière simple. Découvrez les deux façons de configurer les gestionnaires de bot","de":"Die Telegram-Bot-API mit Kotlin-DSL ermöglicht die einfache Definition von Bot-Funktionen. Erfahren Sie die zwei Möglichkeiten, Bot-Handler zu konfigurieren","en":"Telegram Bot API wrapper with handy Kotlin DSL."},"seo":{"title":{"zh":"Telegram Bot API Kotlin DSL ","ja":"Telegram Bot API Kotlin DSL","ko":"Telegram Bot API Kotlin DSL","es":"Configuración de manejadores de bot con Kotlin DSL","fr":"Configuration des gestionnaires de bot avec Kotlin DSL","de":"Einrichtung von Bot-Handlern mit Kotlin DSL","en":"setup-bot-handlers"},"description":{"zh":"Kotlin DSL Telegram Bot API, DSL","ja":"Kotlin DSL Telegram Bot API, DSL","ko":"Kotlin DSL Telegram Bot API, DSL","es":"La API de Telegram Bot con Kotlin DSL permite definir funcionalidades de bot de manera sencilla. Conoce las dos formas de configurar manejadores de bot","fr":"L''API de bot Telegram avec Kotlin DSL permet de définir les fonctionnalités de bot de manière simple. Découvrez les deux façons de configurer les gestionnair...","de":"Die Telegram-Bot-API mit Kotlin-DSL ermöglicht die einfache Definition von Bot-Funktionen. Erfahren Sie die zwei Möglichkeiten, Bot-Handler zu konfigurieren","en":"Telegram Bot API wrapper with handy Kotlin DSL."},"definition":{"en":"Telegram Bot API wrapper with handy Kotlin DSL."},"features":{"zh":["Kotlin DSL","Telegram Bot API","DSL ","CommandHandler","InputHandler"],"ja":["Kotlin DSL","Telegram Bot API","DSL ","CommandHandler","InputHandler"],"ko":["Kotlin DSL","Telegram Bot API","DSL ","CommandHandler","InputHandler"],"es":["Definir funcionalidades de bot con Kotlin DSL","Uso de anotaciones para generar actividades","Carga de manejadores via META-INF","Soporte para comandos y entradas de usuario","Integración con la API de Telegram Bot"],"fr":["Définir les fonctionnalités de bot avec Kotlin DSL","Utilisation d''annotations pour générer des activités","Chargement des gestionnaires via META-INF","Prise en charge des commandes et des entrées utilisateur","Intégration avec l''API de bot Telegram"],"de":["Definieren von Bot-Funktionen mit Kotlin-DSL","Verwendung von Annotationen zur Generierung von Aktivitäten","Laden von Handlern über META-INF","Unterstützung für Befehle und Benutzereingaben","Integration mit der Telegram-Bot-API"]},"keywords":{"zh":["Kotlin DSL","Telegram Bot API","DSL","CommandHandler","InputHandler","KSP","META-INF"],"ja":["Kotlin DSL","Telegram Bot API","DSL","CommandHandler","InputHandler","KSP","META-INF"],"ko":["Kotlin DSL","Telegram Bot API","DSL","CommandHandler","InputHandler","KSP","META-INF"],"es":["bot de Telegram","Kotlin DSL","manejadores de bot","API de Telegram Bot","desarrollo de bots","programación de bots","integración con Telegram"],"fr":["bot Telegram","Kotlin DSL","gestionnaires de bot","API de bot Telegram","développement de bots","programmation de bots","intégration avec Telegram"],"de":["Telegram-Bot","Kotlin-DSL","Bot-Handler","Telegram-Bot-API","Bot-Entwicklung","Bot-Programmierung","Integration mit Telegram"]}},"owner":"vendelieu","repo":"telegram-bot","repoPath":"vendelieu/telegram-bot","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.539Z","topics":[],"category":"community","skillMd":{"name":"setup-bot-handlers","description":"[Bot developer] Sets up bot handlers using DSL or annotations. Use when configuring command handlers, input handlers, common handlers, update handlers, or fallback handlers for the telegram-bot library.","bodyPreview":"# Setup Bot Handlers\n\n## Two Approaches\n\n- **DSL**: `bot.setFunctionality { ... }` — define handlers inline\n- **Annotations**: `@CommandHandler`, `@InputHandler`, etc. — KSP generates activities; use with `bot.handleUpdates()` (loads handlers via META-INF)\n\n## DSL Handlers\n\nInside `bot.setFunctionality { }`:\n\n| Handler | Purpose |\n|---------|---------|\n| `onCommand(\"/start\") { }` | Commands (e.g. /start) |\n| `onInput(\"id\") { }` | Single-step input; route via `bot.inputListener[user] = \"id\"` |\n|","body":"# Setup Bot Handlers\n\n## Two Approaches\n\n- **DSL**: `bot.setFunctionality { ... }` — define handlers inline\n- **Annotations**: `@CommandHandler`, `@InputHandler`, etc. — KSP generates activities; use with `bot.handleUpdates()` (loads handlers via META-INF)\n\n## DSL Handlers\n\nInside `bot.setFunctionality { }`:\n\n| Handler | Purpose |\n|---------|---------|\n| `onCommand(\"/start\") { }` | Commands (e.g. /start) |\n| `onInput(\"id\") { }` | Single-step input; route via `bot.inputListener[user] = \"id\"` |\n| `inputChain(\"id\") { }.andThen { }` | Multi-step input chain |\n| `common(\"text\") { }` or `common(Regex(\"...\")) { }` | Text/regex match (lower priority than commands) |\n| `onUpdate(UpdateType.X) { }` | All updates of given type |\n| `whenNotHandled { }` | Fallback for unprocessed updates |\n\n## Typed Update Handlers\n\nUse typed wrappers for `ActivityCtx<XxxUpdate>`:\n\n- `onMessage { }` — `MessageUpdate`\n- `onCallbackQuery { }` — `CallbackQueryUpdate`\n- `onInlineQuery { }` — `InlineQueryUpdate`\n- `onEditedMessage { }`, `onChannelPost { }`, `onChatMember { }`, etc.\n\n## Input Listener\n\nRoute the next user message to an input handler or chain:\n\n```kotlin\nbot.inputListener[user] = \"conversation\"\n// or\nbot.inputListener.set(user) { \"conversation-2step\" }\n```\n\n## Annotation Handlers\n\n| Annotation | Purpose |\n|------------|---------|\n| `@CommandHandler([\"/start\"])` | Command handler |\n| `@CommandHandler.CallbackQuery([\"/data\"])` | Callback query with optional `autoAnswer` |\n| `@InputHandler([\"id\"])` | Input handler |\n| `@CommonHandler.Text([\"value\"])` or `@CommonHandler.Regex(\"...\")` | Text/regex match |\n| `@UpdateHandler([UpdateType.MESSAGE, ...])` | Update type handler |\n| `@UnprocessedHandler` | Fallback |\n\n## Guards\n\nAdd pre-processing checks:\n\n- DSL: `guard = UserPresentGuard::class` (or `DefaultGuard::class`)\n- Annotation: `@Guard(UserPresentGuard::class)` or `@Guard(guard = UserPresentGuard::class)`\n\nSupported by: CommandHandler, CommandHandler.CallbackQuery, InputHandler.\n\n## Rate Limits\n\n- DSL: `rateLimits = RateLimits.NOT_LIMITED` or custom\n- Annotation: `@RateLimits(period = 60_000, rate = 5)` — 5 requests per 60 seconds\n- Default: no limit\n\nSupported by: CommandHandler, CallbackQuery, InputHandler, CommonHandler.\n\n## ArgParser\n\nCustom argument parsing for commands and callback data:\n\n- Annotation: `@ArgParser(argParser = CustomArgParser::class)`\n- Supported by: CommandHandler, CallbackQuery, CommonHandler\n- Default: `DefaultArgParser`\n\n## Annotation Reference\n\n| Annotation | Parameters | Default |\n|------------|------------|---------|\n| `@CommandHandler` | `value` (commands), `scope` (UpdateType[]) | scope: MESSAGE |\n| `@CommandHandler.CallbackQuery` | `value` (callback data prefixes), `autoAnswer` (bool) | autoAnswer: false |\n| `@InputHandler` | `value` (input identifiers) | — |\n| `@CommonHandler.Text` | `value`, `filters`, `priority`, `scope` | filters: [], priority: 0, scope: MESSAGE |\n| `@CommonHandler.Regex` | `value` (pattern), `options`, `filters`, `priority`, `scope` | options: [], filters: [], priority: 0, scope: MESSAGE |\n| `@UpdateHandler` | `type` (UpdateType[]) | — |\n| `@UnprocessedHandler` | — | — |\n| `@Guard` | `guard` (KClass) | DefaultGuard |\n| `@ArgParser` | `argParser` (KClass) | DefaultArgParser |\n| `@RateLimits` | `period` (ms), `rate` (requests) | 0, 0 |\n\n## Reference\n\n- [CommandHandler.kt](telegram-bot/src/commonMain/kotlin/eu/vendeli/tgbot/annotations/CommandHandler.kt)\n- [CommonHandler.kt](telegram-bot/src/commonMain/kotlin/eu/vendeli/tgbot/annotations/CommonHandler.kt)\n- [FunctionalHandlingDsl.kt](telegram-bot/src/commonMain/kotlin/eu/vendeli/tgbot/core/FunctionalHandlingDsl.kt)\n- [FunctionalDSLUtils.kt](telegram-bot/src/commonMain/kotlin/eu/vendeli/tgbot/utils/common/FunctionalDSLUtils.kt)\n- [telegram-bot-handling.mdc](.cursor/rules/telegram-bot-handling.mdc)\n"},"lastSynced":"2026-02-19T01:13:06.130Z","qualityScore":55}');
