INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('s-hiraoku/vscode-sidebar-terminal/synapse-a2a', 'community', 's-hiraoku', 'vscode-sidebar-terminal', 's-hiraoku/vscode-sidebar-terminal', 'synapse-a2a', 0, 0, 70, '2026-02-18T01:03:48.182Z', '2026-02-19T06:01:12.128Z', NULL, '{"id":"s-hiraoku/vscode-sidebar-terminal/synapse-a2a","name":"synapse-a2a","description":{"zh":"Synapse A2A 是一个 Inter-agent 通信框架，用于实现 agent 之间的通信。它提供了列表、发送消息、广播和等待回复等功能。","ja":"Synapse A2A はエージェント間の通信を実現する Inter-agent 通信フレームワークです。リスト表示、メッセージ送信、ブロードキャスト、応答待ちなどを提供します。","ko":"Synapse A2A는 에이전트 간의 통신을 구현하는 Inter-agent 통신 프레임워크입니다. 리스트 표시, 메시지 전송, 방송 및 응답 대기 등이 제공됩니다.","es":"Synapse A2A es un framework de comunicación entre agentes que permite la interacción entre ellos mediante el protocolo Google A2A. Ofrece comandos para listar agentes, enviar mensajes y broadcastear","fr":"Synapse A2A est un framework de communication entre agents qui permet l''interaction entre eux via le protocole Google A2A. Il offre des commandes pour lister les agents, envoyer des messages et diffuser","de":"Synapse A2A ist ein Framework für die Kommunikation zwischen Agenten, das die Interaktion zwischen ihnen über das Google A2A-Protokoll ermöglicht. Es bietet Befehle zum Auflisten von Agenten, Senden von Nachrichten und Broadcasten","pt":"O Synapse A2A é um framework de comunicação entre agentes que permite a troca de mensagens via Protocolo Google A2A. Ele oferece comandos para listar agentes, enviar mensagens e broadcast.","ru":"Synapse A2A - это фреймворк для межагентского общения, позволяющий обмениваться сообщениями через протокол Google A2A. Он предоставляет команды для списка агентов, отправки сообщений и передачи.","ar":"سينابس A2A هو إطار عمل اتصال وسيط بين الوكلاء الذي يسمح بالتبادل الرسائل عبر بروتوكول جوجل A2A. يقدم أوامر لاستعراض الوكلاء وإرسال الرسائل والبث.","en":""},"seo":{"title":{"zh":"Synapse